theme.globalCss:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:ital,wght@0,300;0,400;0,500;1,300;1,400;1,500&family=Inter:wght@300;400;500;600&family=Space+Grotesk:wght@300;400;500;600;700&family=Space+Mono&display=swap');

body {
  font-family: 'Inter', sans-serif;
}

.font-mono {
  font-family: 'Space Mono', monospace;
}

.no-scrollbar::-webkit-scrollbar {
    display: none;
}

.no-scrollbar {
    -ms-overflow-style: none;
    scrollbar-width: none;
}

/* Volturiano Stamp Styles */
.stampWrapper {
  display: flex;
  justify-content: center;
  align-items: center;
  margin-top: 3rem;
  padding-top: 2rem;
  border-top: 1px solid rgba(255,255,255,0.1);
}

.volturianoStamp {
  display: inline-flex;
  align-items: center;
  justify-content: flex-start;
  gap: 0;
  padding: 0px 5px;
  width: 55px;
  height: 55px;
  border-radius: 14px;
  text-decoration: none;
  overflow: hidden;
  white-space: nowrap;
  border: 2px solid transparent;
  background-image: linear-gradient(to bottom, #0a0a0a, #141414), linear-gradient(135deg, rgba(255,255,255,0.9) 0%, rgba(80,80,80,0.5) 50%, rgba(255,255,255,0.8) 100%);
  background-origin: padding-box, border-box;
  background-clip: padding-box, border-box;
  box-shadow: 0px 4px 30px -5px rgba(255, 255, 255, 0.15);
  transition: width 0.5s cubic-bezier(0.25, 0.8, 0.25, 1), padding 0.5s cubic-bezier(0.25, 0.8, 0.25, 1), box-shadow 0.3s ease, transform 0.3s ease;
  margin-top: 16px;
  align-self: flex-end;
  transform: scale(0.8);
  transform-origin: right center;
}

.volturianoStamp:hover {
  width: 230px;
  padding: 0px 20px;
  box-shadow: 0px 8px 40px -4px rgba(255, 255, 255, 0.35);
  transform: scale(0.8) translateY(-2px);
}

.stampContent {
  display: flex;
  align-items: center;
  gap: 15px;
  opacity: 0;
  max-width: 0;
  padding-right: 0;
  overflow: hidden;
  transition: max-width 0.5s cubic-bezier(0.25, 0.8, 0.25, 1), opacity 0.4s ease-out, padding-right 0.5s cubic-bezier(0.25, 0.8, 0.25, 1), transform 0.4s ease-out;
  transform: translateX(10px);
}

.volturianoStamp:hover .stampContent {
  opacity: 1;
  max-width: 200px;
  padding-right: 15px;
  transform: translateX(0);
}

.stampText {
  position: relative;
  z-index: 2;
  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display", "Segoe UI", Roboto, sans-serif;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: 2.5px;
  text-transform: uppercase;
  background: linear-gradient(to bottom, #ffffff 0%, #b0b0b0 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 2px 4px rgba(0,0,0,0.5));
  white-space: nowrap;
}

.stampSeparator {
  width: 1.5px;
  height: 24px;
  background: linear-gradient(to bottom, #ffffff, rgba(255,255,255,0.5));
  border-radius: 10px;
  opacity: 0.9;
  margin-top: 2px;
  flex-shrink: 0;
  display: block;
}

.stampLogo {
  height: 45px;
  width: auto;
  display: block;
  filter: brightness(0) invert(1);
  opacity: 0.95;
  margin-top: -1px;
  flex-shrink: 0;
  margin-left: auto;
  margin-right: auto;
}
